// RegisterCodeOrchestrationTools registers the agent-facing tools that cover
// the whole API surface. Called from RegisterTools in place of the per-endpoint
// registrations when MCP.Orchestration is "code".
func RegisterCodeOrchestrationTools(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("tailscale_search",
			mcplib.WithDescription("Search the tailscale API for endpoints matching a natural-language query. Returns a ranked list of {endpoint_id, method, path, summary} entries. Call this first to find the endpoint to execute."),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Natural-language description of what you want to do.")),
			mcplib.WithNumber("limit", mcplib.Description("Max endpoints to return (default 10, max 100).")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(false),
		),
		handleCodeOrchSearch,
	)

	s.AddTool(
		mcplib.NewTool("tailscale_get",
			mcplib.WithDescription("Get metadata for one GET endpoint by its endpoint_id (from tailscale_search). This registry-only lookup never calls the API."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("GET endpoint identifier returned by tailscale_search (e.g., \"users.list\").")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(false),
		),
		handleCodeOrchGet,
	)

	s.AddTool(
		mcplib.NewTool("tailscale_execute",
			// PATCH(mcp-remote-writes-need-explicit-confirm): writes return a plan unless confirm=true.
			mcplib.WithDescription("Execute one tailscale API endpoint by its endpoint_id (from tailscale_search). Params are passed as a JSON object; path placeholders and query strings are resolved automatically. Write endpoints (POST/PUT/PATCH/DELETE, except policy validate and preview) return the planned request and send nothing unless confirm is true."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("Endpoint identifier returned by tailscale_search (e.g., \"users.list\").")),
			mcplib.WithObject("params", mcplib.Description("Parameters for the endpoint. Path placeholders match by name; remaining entries become query string on GET/DELETE or JSON body on POST/PUT/PATCH.")),
			mcplib.WithBoolean("confirm", mcplib.Description("Set true to send a write request. Without it a write endpoint returns its plan only.")),
		),
		handleCodeOrchExecute,
	)
}

